// Format response into ko/en HTML and run 12-check + no-ai-copy gates.
const draft = JSON.parse($json.content?.[0]?.text || '{}');
const ko = draft.ko || {};
const en = draft.en || {};
const SECTIONS = ['intro','trend_snapshot','how_to_use','cultural_context','editor_picks','closing','source'];

const AI_COPY = /AI(-| )(generated|curated|powered)|AI가 정리|자동 생성 콘텐츠|Generated:/i;
const MEDICAL_GUARD = /(발암|의료사고|치료해\s*드립니다|완치|부작용\s*없음)/;
const EFFICACY_ASSERT = /(에\s*좋다|를\s*낫게\s*해|을\s*없애준다)/;

function renderHtml(side, lang) {
  const t = side.title || '';
  const sx = side.sections || {};
  const items = (sx.how_to_use || '').split(/\n+/).filter(Boolean);
  const list = items.map((l) => `        <li>${l.replace(/^\d+[\).\s-]*/,'')}</li>`).join('\n');
  return [
    `<!DOCTYPE html>`,
    `<html lang="${lang}">`,
    `<head>`,
    `<meta charset="UTF-8">`,
    `<meta name="viewport" content="width=device-width, initial-scale=1.0">`,
    `<meta name="description" content="${(sx.intro || '').replace(/"/g,'&quot;').slice(0,200)}">`,
    `<meta name="category" content="k-beauty">`,
    `<title>${t}</title>`,
    `</head>`,
    `<body>`,
    `<h1>${t}</h1>`,
    `<div class="meta">Language: ${lang === 'ko' ? '한국어' : 'English'} · Editor's Curation · K-Beauty</div>`,
    `<h3>${lang === 'ko' ? '들어가며' : 'Intro'}</h3><p>${sx.intro || ''}</p>`,
    `<h3>${lang === 'ko' ? '트렌드 스냅샷' : 'Trend Snapshot'}</h3><p>${sx.trend_snapshot || ''}</p>`,
    `<h3>${lang === 'ko' ? '에디터 추천 루틴' : 'How To Use'}</h3>`,
    `<ul>\n${list}\n</ul>`,
    `<h3>${lang === 'ko' ? '한국 뷰티 문화의 맥락' : 'Cultural Context'}</h3><p>${sx.cultural_context || ''}</p>`,
    `<h3>${lang === 'ko' ? '에디터 픽' : 'Editor Picks'}</h3><p>${sx.editor_picks || ''}</p>`,
    `<h3>${lang === 'ko' ? '마무리' : 'Closing'}</h3><p>${sx.closing || ''}</p>`,
    `<h3>${lang === 'ko' ? '출처' : 'Source'}</h3><p>${sx.source || ''}</p>`,
    `</body>`,
    `</html>`
  ].join('\n');
}

const koHtml = renderHtml(ko, 'ko');
const enHtml = renderHtml(en, 'en');
const koTextOnly = koHtml.replace(/<[^>]+>/g,' ');
const enTextOnly = enHtml.replace(/<[^>]+>/g,' ');

const checks = {
  '01_ko_title_present': !!ko.title,
  '02_en_title_present': !!en.title,
  '03_ko_slug_kebab': /^[a-z0-9-]+$/.test(ko.slug || ''),
  '04_en_slug_kebab': /^[a-z0-9-]+$/.test(en.slug || ''),
  '05_all_sections_ko': SECTIONS.every((s) => (ko.sections || {})[s]),
  '06_all_sections_en': SECTIONS.every((s) => (en.sections || {})[s]),
  '07_ko_min_length_600': koTextOnly.replace(/\s+/g,'').length >= 600,
  '08_en_min_words_200': enTextOnly.split(/\s+/).filter(Boolean).length >= 200,
  '09_no_ai_copy': !AI_COPY.test(koTextOnly) && !AI_COPY.test(enTextOnly),
  '10_medical_guard': !MEDICAL_GUARD.test(koTextOnly) && !MEDICAL_GUARD.test(enTextOnly),
  '11_no_efficacy_assert': !EFFICACY_ASSERT.test(koTextOnly),
  '12_category_meta': /name=\"category\"\s+content=\"k-beauty\"/.test(koHtml) && /name=\"category\"\s+content=\"k-beauty\"/.test(enHtml)
};

// >>> JAC-1895 hexagon-anchor-backlink BEGIN

// Hexagon mode is opt-in via `body.hexagon_id`. When absent, we auto-pass to

// preserve the legacy single-article daily routine. Sister domains in hexagon

// mode must include the anchor slug (the hexagon_id) somewhere in body+meta —

// flexible enough to match `/dramas/<id>` or `/content/reviews/<id>-ko.html`

// or any other URL the publish layer adopts. The k-drama anchor self-passes.

const hxTrigger = $('Webhook Trigger').first().json.body || {};

const hxId = hxTrigger.hexagon_id || null;

const hxCategory = "k-beauty";

let hxBacklinkOk;

if (!hxId) {

  hxBacklinkOk = true; // legacy mode

} else {

  hxBacklinkOk = ((koTextOnly + ' ' + enTextOnly) || '').includes(hxId);

}

checks['14_anchor_backlink_present'] = hxBacklinkOk;

// <<< JAC-1895 hexagon-anchor-backlink END

const passed = Object.values(checks).filter(Boolean).length;
const total = Object.keys(checks).length;
const pass = passed === total;

return [{ json: {
  category: 'k-beauty',
  ko: { title: ko.title, slug: ko.slug, html: koHtml, korean_chars: koTextOnly.replace(/\s+/g,'').length },
  en: { title: en.title, slug: en.slug, html: enHtml, en_word_count: enTextOnly.split(/\s+/).filter(Boolean).length },
  checks, passed, total, pass,
  ai_copy_hit: AI_COPY.test(koTextOnly + enTextOnly) ? AI_COPY.exec(koTextOnly + enTextOnly)[0] : null,
  blocked_keyword_hit: MEDICAL_GUARD.test(koTextOnly + enTextOnly) ? MEDICAL_GUARD.exec(koTextOnly + enTextOnly)[0] : null
}}];
